import { RequestMethods } from '06_shared/types/types';
import { baseQuery } from '06_shared/api/baseQuery';
import { createApi } from '@reduxjs/toolkit/query/react';
import { statisticTradeByDayActions } from '../../model/slice/statisticTradeByDaySlice';
export const statisticTradeByDayApi = createApi({
    reducerPath: 'statisticTradeByDayApi',
    tagTypes: ['statisticTradeByDay'],
    baseQuery: baseQuery,
    endpoints: (builder) => ({
        getStatisticTradeByDay: builder.query({
            query: () => ({
                url: '/public/statistics/daily',
                method: RequestMethods.GET,
            }),
            providesTags: ['statisticTradeByDay'],
            async onQueryStarted(arg, { dispatch, queryFulfilled }) {
                try {
                    const { data } = await queryFulfilled;
                    if (!data?.result)
                        return;
                    dispatch(statisticTradeByDayActions.setStatisticTradeByDay(data.result));
                }
                catch (e) {
                    console.error('Error in queryFulfilled getStatisticTradeByDay', e);
                }
            },
        }),
    }),
});
export const { useGetStatisticTradeByDayQuery, } = statisticTradeByDayApi;
