import { RequestMethods } from '06_shared/types/types';
import { baseQuery } from '06_shared/api/baseQuery';
import { createApi } from '@reduxjs/toolkit/query/react';
import { TradeStatusEnum, } from '05_entities/trade';
import { tradeHistoryActions } from '../../model/slice/tradeHistorySlice';
import { buildSearchParams } from '06_shared/utils/buildSearchParams';
const HISTORY_TRADE_STATUSES = [
    TradeStatusEnum.CLOSE,
    TradeStatusEnum.STOP_LOSS,
    TradeStatusEnum.TREILING_STOP,
    TradeStatusEnum.TAKE_PROFIT,
    TradeStatusEnum.DIRECTION_SIGNAL,
    TradeStatusEnum.REVERSE_SIGNAL,
    TradeStatusEnum.MANUAL_CLOSE,
];
export const tradeHistoryApi = createApi({
    reducerPath: 'tradeHistoryApi',
    tagTypes: ['tradeHistoryList'],
    baseQuery: baseQuery,
    endpoints: (builder) => ({
        getTradeHistoryList: builder.query({
            query: (dateRange) => ({
                url: `/trades?${buildSearchParams({
                    trade_statuses: HISTORY_TRADE_STATUSES,
                    limit: -1,
                    offset: 0,
                    create_start_ts: dateRange?.start_date
                        ? new Date(dateRange.start_date).getTime()
                        : undefined,
                    create_end_ts: dateRange?.end_date
                        ? new Date(dateRange.end_date).getTime()
                        : undefined,
                })}`,
                method: RequestMethods.GET,
            }),
            providesTags: ['tradeHistoryList'],
            async onQueryStarted(arg, { dispatch, queryFulfilled }) {
                try {
                    const { data } = await queryFulfilled;
                    dispatch(tradeHistoryActions.calculateRealizedPNL(data?.result?.items ?? []));
                }
                catch (e) {
                    console.error('Error in queryFulfilled getTradeHistoryList', e);
                }
            }
        }),
    }),
});
export const { useGetTradeHistoryListQuery, } = tradeHistoryApi;
