import { RequestMethods } from '06_shared/types/types';
import { baseQuery } from '06_shared/api/baseQuery';
import { createApi } from '@reduxjs/toolkit/query/react';
export const symbolApi = createApi({
    reducerPath: 'symbolApi',
    tagTypes: ['symbol'],
    baseQuery: baseQuery,
    endpoints: (builder) => ({
        getAvailableSymbolsDict: builder.query({
            query: () => ({
                url: '/symbols',
                method: RequestMethods.GET,
            }),
            providesTags: ['symbol'],
        }),
    }),
});
export const { useGetAvailableSymbolsDictQuery, } = symbolApi;
