import { RequestMethods } from '06_shared/types/types';
import { baseQuery } from '06_shared/api/baseQuery';
import { createApi } from '@reduxjs/toolkit/query/react';
export const platformPreferencesApi = createApi({
    reducerPath: 'platformPreferencesApi',
    tagTypes: ['platformPreferences'],
    baseQuery: baseQuery,
    endpoints: (builder) => ({
        getPlatformPreferences: builder.query({
            query: (platform_uuid) => ({
                url: `/platform-preferences/${platform_uuid}`,
                method: RequestMethods.GET,
            }),
            providesTags: ['platformPreferences'],
        }),
        setPlatformPreferences: builder.mutation({
            query: ({ platform_uuid, ...body }) => ({
                url: `/platform-preferences/${platform_uuid}`,
                method: RequestMethods.PUT,
                body,
            }),
            invalidatesTags: ['platformPreferences'],
        }),
    }),
});
export const { useGetPlatformPreferencesQuery, useSetPlatformPreferencesMutation, } = platformPreferencesApi;
